function puzzleVocabulary(s,r){let seen=new Set(),clean=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z]/g,'');let families=new Set();let v=shuffle(s.facts.filter(f=>!f.case&&r.topics.includes(f.topic)&&!f.puzzleExclude15&&f.term.split(/\s+/).length<=4)).map(f=>{let masked=maskedDefinition(f),word=clean(f.term),answerMatch=clean(f.a)===word&&clean(f.q).indexOf(word)===-1,explicit=masked!==f.definition&&clean(masked).indexOf(word)===-1,authored=f.clue12&&clean(f.clue12).indexOf(word)===-1;return {term:f.term,word,clue:authored?f.clue12:explicit?masked.replaceAll('[term]','_____'):answerMatch?f.q:f.definition,explicit:!!authored||explicit||answerMatch,family15:f.family15};}).filter(x=>x.word.length>=3&&x.word.length<=20&&!seen.has(x.word)&&seen.add(x.word)).sort((a,b)=>Number(b.explicit)-Number(a.explicit)).filter(x=>!x.family15||(!families.has(x.family15)&&families.add(x.family15)));return v;}
