 if(type==='Sequencing'){if(f.format!==type||!f.steps?.length)return null;let scrambled=shuffle(f.steps);if(scrambled.every((v,i)=>v===f.steps[i]))scrambled.push(scrambled.shift());prompt=f.q+' Write the letters in order: '+scrambled.map((step,i)=>String.fromCharCode(65+i)+'. '+step).join(' | ');answer=f.steps.map(step=>String.fromCharCode(65+scrambled.indexOf(step))).join(' – ')+'; '+f.steps.join(' → ');marks=f.steps.length;}
